<?php if(!$items):?><div class="km-card p-5 text-center"><div style="font-size:3rem">⌕</div><h4 class="fw-800 mt-2">Aucun produit trouvé</h4><p class="text-muted">Essayez un autre mot-clé ou un autre rayon.</p><a class="btn btn-km" href="<?=e(base_url('catalog'))?>">Voir tout le catalogue</a></div><?php else:?><div class="product-grid"><?php foreach($items as $p): $disc=discount_percent($p);?><article class="shop-product"><a class="text-decoration-none text-dark" href="<?=e(base_url('product/'.$p['id']))?>"><div class="product-media"><img src="<?=e(product_image_url($p))?>" alt="<?=e($p['name'])?>"><div class="product-badges"><?php if($disc):?><span class="promo-badge">-<?=$disc?>%</span><?php endif;?><span class="fresh-badge"><?=e($p['category'])?></span></div></div><div class="product-body"><div class="product-category"><?=e($p['category'])?></div><div class="product-title"><?=e($p['name'])?></div><div class="product-meta"><span class="stock-chip">Disponible</span><span><?=e($p['available_qty'])?> en stock</span></div><div class="product-price"><span class="now"><?=money($p['effective_price'])?></span><?php if($disc):?><span class="was"><?=money($p['sale_price'])?></span><?php endif;?></div></div></a><form method="post" action="<?=e(base_url('cart/add'))?>" class="product-action"><?=csrf_field()?><input type="hidden" name="product_id" value="<?=$p['id']?>"><input type="hidden" name="qty" value="1"><input type="hidden" name="return_to" value="catalog<?= $category?'?category='.(int)$category:'' ?>"><button class="btn btn-km">🛒 Ajouter</button></form></article><?php endforeach;?></div><?php endif;?></section></div>
